import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import {
  RewardBindingError,
  computeRewardBinding,
  rewardBindingFromCoinbase,
  rewardPayability,
} from '../src/utils/upi-reward-binding'

// Golden fixtures shared verbatim with shawn-local-skills (pay-invoice) and
// MuggleLink. Expected fingerprints were generated by an independent Python
// implementation, not by the module under test.
const golden = JSON.parse(
  readFileSync(fileURLToPath(new URL('./fixtures/upi-reward-binding-v1.golden.json', import.meta.url)), 'utf8'),
) as {
  version: string
  cases: Array<{ name: string; input: any; expected?: { canonical_json: string; fingerprint: string }; expected_error?: string }>
  payload_cases: Array<{ name: string; payload: any; expected_fingerprint?: string; expected_error?: string }>
}

async function errorCode(p: Promise<unknown>): Promise<string> {
  try {
    await p
  } catch (e) {
    expect(e).toBeInstanceOf(RewardBindingError)
    return (e as RewardBindingError).code
  }
  throw new Error('expected a RewardBindingError')
}

describe('upi-reward-binding-v1 golden fixtures', () => {
  it('has enough coverage (v1, v3, rejections)', () => {
    expect(golden.version).toBe('upi-reward-binding-v1')
    expect(golden.cases.filter((c) => c.expected).length).toBeGreaterThanOrEqual(3)
    expect(golden.cases.filter((c) => c.expected_error).length).toBeGreaterThanOrEqual(3)
  })

  for (const c of golden.cases) {
    it(`input: ${c.name}`, async () => {
      if (c.expected) {
        const b = await computeRewardBinding(c.input)
        expect(b.canonical_json).toBe(c.expected.canonical_json)
        expect(b.fingerprint).toBe(c.expected.fingerprint)
      } else {
        expect(await errorCode(computeRewardBinding(c.input))).toBe(c.expected_error)
      }
    })
  }

  for (const c of golden.payload_cases) {
    it(`payload: ${c.name}`, async () => {
      if (c.expected_fingerprint) {
        expect((await rewardBindingFromCoinbase(c.payload)).fingerprint).toBe(c.expected_fingerprint)
      } else {
        expect(await errorCode(rewardBindingFromCoinbase(c.payload))).toBe(c.expected_error)
      }
    })
  }
})

describe('rewardPayability', () => {
  const now = Date.parse('2026-10-28T00:00:00Z')
  it('v1: usage and expiry, fail closed', () => {
    const base = { id: 'pl_1', usageCount: 0, maxUsage: 1, preApprovalExpiry: String(now / 1000 + 600) }
    expect(rewardPayability(base, now).payable).toBe(true)
    expect(rewardPayability({ ...base, usageCount: 1 }, now).reason).toBe('already_used')
    expect(rewardPayability({ ...base, usageCount: undefined }, now).reason).toBe('usage_unverifiable')
    expect(rewardPayability({ ...base, preApprovalExpiry: String(now / 1000 - 1) }, now).reason).toBe('expired')
    expect(rewardPayability({ ...base, preApprovalExpiry: 'soon' }, now).reason).toBe('expiry_unverifiable')
  })
  it('v3: only CREATED and unexpired', () => {
    const base = { paymentSessionId: 'paymentSession_x', status: 'PAYMENT_SESSION_STATUS_CREATED', expiresAt: new Date(now + 60_000).toISOString() }
    expect(rewardPayability(base, now).payable).toBe(true)
    expect(rewardPayability({ ...base, status: 'PAYMENT_SESSION_STATUS_AUTHORIZATION_PENDING' }, now).reason).toBe('not_payable_state')
    expect(rewardPayability({ ...base, expiresAt: new Date(now - 1).toISOString() }, now).reason).toBe('expired')
  })
})
